    @field_validator('numbers', mode='after')
    @classmethod
    def check_sum(cls, v: list[int]) -> list[int]:
        if sum(v) > 100:
            raise ValueError('sum too large')
        return v

    # Runs BEFORE type validation (receives raw input)
    @field_validator('numbers', mode='before')
    @classmethod
