    @classmethod
    def parse_value(cls, v):
        if isinstance(v, str):
            return int(v.replace(',', ''))
        return v

    @field_validator('value', mode='after')    # default: runs AFTER type validation
    @classmethod
    def check_value(cls, v: int) -> int:
        return v
